function deriveStatus(p: any, observed: any): { status: string; basis: string } {
  if (p.softDeletedInSource) return { status: 'archived', basis: 'Soft-deleted in the source export (deletion timestamp present in the source record).' };
  if (p.productClass === 'internal') return { status: 'archived', basis: 'Internal test record in the source export.' };
  if (observed?.lastSale) {
    const days = Math.round((Date.parse('2026-10-16') - Date.parse(observed.lastSale)) / 86400000);
    if (days <= 120) return { status: 'active', basis: `Sold in the Bengaluru sales export within the last ${days} days (${observed.lastSale}).` };
    if (days <= 400) return { status: 'historical', basis: `Last observed sale ${observed.lastSale}; no recent sales in the export.` };
    return { status: 'historical', basis: `Last observed sale ${observed.lastSale}.` };
  }
  // A record only enters the manual-review queue when something in the source is
  // genuinely unresolved. "Never sold in this window" is a fact worth showing, not a defect.
  const warnings: string[] = p.warnings ?? [];
  const has = (prefix: string) => warnings.some((w: string) => w.startsWith(prefix));
  const creditBearing = (p.price ?? 0) > 0 && !p.unlimitedAccess && p.productClass !== 'complimentary' && p.productClass !== 'operational';
  const flags: string[] = [];
  if (has('duration_not_recovered')) flags.push('validity could not be recovered from the source row');
  if (has('implausible_price_per_credit')) flags.push('price per credit is implausible, so the credit count needs confirmation');
  if (has('credits_not_recovered') && creditBearing) flags.push('credit count could not be recovered for a credit-based product');
  if (has('credits_derived_from_unlabelled_source_token') && creditBearing) flags.push('credit count inferred from an unlabelled number in the source row — confirm before quoting');
  if (flags.length) return { status: 'review', basis: `Flagged for manual review: ${flags.join('; ')}.` };

  if (p.productClass === 'complimentary' || p.productClass === 'operational') {
    // Kept and shown for traceability, excluded from offer generation, and never
    // counted as a retail membership or as a manual-review workload item.
    return { status: 'archived', basis: 'Non-retail record (complimentary class, comp membership, internal ops or host entry). Retained for traceability; excluded from offer generation.' };
  }
  if (p.modifiedAt && Date.parse(p.modifiedAt) < Date.parse('2025-06-01')) {
    return { status: 'historical', basis: 'Not sold in the observed Bengaluru export and unchanged in the source since mid-2025 — availability to be confirmed.' };
  }
  return { status: 'active', basis: 'Present in the source catalogue; no conflicting signals found during parsing.' };
}

const EXPIRY_WINDOW = ['2026-10-28', '2026-11-06', '2026-11-19', '2026-12-31', '2026-11-30', '2026-10-24'];

export function runSeed(db: Database.Database) {
  const parsed = JSON.parse(fs.readFileSync(path.join(DATA_DIR, 'derived', 'catalogue.parsed.json'), 'utf8')) as any[];
  const sales = readDerivedJson<any>('sales_performance.json');
  const funnel = readDerivedJson<any>('lead_funnel.json');
  const customerBase = readDerivedJson<any>('customer_base.json');
  const capacity = readDerivedJson<any>('capacity_utilisation.json');
  const evidence: EvidenceContext = { sales, funnel, customerBase, capacity };

  const observedIndex = new Map<string, any>();
  for (const p of sales?.products ?? []) {
    observedIndex.set(normaliseName(p.product), p);
  }

  const tx = db.transaction(() => {
    // ---------------------------------------------------------------- wipe
    for (const t of ['performance_records', 'notifications', 'ai_generations', 'imports', 'activity', 'comments', 'approvals', 'offer_versions', 'offers', 'campaigns', 'catalogue_versions', 'catalogue_products', 'collections', 'sessions', 'users', 'locations', 'settings']) {
      db.exec(`DELETE FROM ${t}`);
    }

    // ---------------------------------------------------------------- locations & users
    const locStmt = db.prepare(`INSERT INTO locations (id,name,short_name,city,brand,active) VALUES (@id,@name,@shortName,@city,@brand,1)`);
    LOCATIONS.forEach(l => locStmt.run(l));

    const userStmt = db.prepare(`INSERT INTO users (id,name,email,password_hash,role,title,avatar_color,created_at) VALUES (?,?,?,?,?,?,?,?)`);
    const pwHash = hashPassword(DEMO_PASSWORD);
    USERS.forEach(u => userStmt.run(u.id, u.name, u.email, pwHash, u.role, u.title, u.color, '2026-08-01T05:00:00.000Z'));

    // ---------------------------------------------------------------- catalogue
    const catStmt = db.prepare(`INSERT INTO catalogue_products (
      id, source_id, source_file, source_index, raw_block, raw_block_hash, name, product_class, exclusion_reason,
      status, status_basis, location_id, price, price_type, duration, duration_unit, duration_days, credits,
      complimentary_credits, credit_source, unlimited_access, private_session_count, is_intro_offer,
      audience_restriction, description, benefits_json, policies_json, eligibility_json, observed_json, tags_json,
      parse_confidence, warnings_json, manual_review_note, soft_deleted, created_at, modified_at, version, updated_at, updated_by)
      VALUES (@id,@source_id,@source_file,@source_index,@raw_block,@raw_block_hash,@name,@product_class,@exclusion_reason,
      @status,@status_basis,@location_id,@price,@price_type,@duration,@duration_unit,@duration_days,@credits,
      @complimentary_credits,@credit_source,@unlimited_access,@private_session_count,@is_intro_offer,
      @audience_restriction,@description,@benefits_json,@policies_json,@eligibility_json,@observed_json,@tags_json,
      @parse_confidence,@warnings_json,@manual_review_note,@soft_deleted,@created_at,@modified_at,1,@updated_at,'usr_jimmeey')`);

    const catalogue: CatalogueProduct[] = [];
    for (const p of parsed) {
      const id = `cat_${p.sourceId}`;
      const observed = observedIndex.get(normaliseName(p.name)) ?? observedIndex.get(normaliseName(OBSERVED_ALIASES[normaliseName(p.name)] ?? '')) ?? null;
      const { status, basis } = deriveStatus(p, observed);
      const locationId = LOCATION_NAME_TO_ID[p.location] ?? 'p57-blr-vmr';
      const benefits: string[] = [];
      if (p.policy?.complimentaryPrivateClasses) benefits.push(`${p.policy.complimentaryPrivateClasses} complimentary private classes`);
      if (p.policy?.guestPasses) benefits.push(`${p.policy.guestPasses} guest passes`);
      if (p.policy?.retailDiscountPct) benefits.push(`${p.policy.retailDiscountPct}% off retail products`);
      if (p.policy?.workshopAccess) benefits.push('Free workshop access and priority booking');
      if (p.policy?.freezeAllowance != null) benefits.push(p.policy.freezeAllowance > 0 ? `${p.policy.freezeAllowance} freeze(s) per term` : 'No freezes included');
      if (p.policy?.lateCancellationWindowHours) benefits.push(`${p.policy.lateCancellationWindowHours}-hour late cancellation window`);
      const eligibility = {
        newClientsOnly: Boolean(p.isIntroOffer),
        firstPurchaseOnly: Boolean(p.isIntroOffer),
        locationRestricted: Boolean(p.policy?.locationExclusive) || locationId !== 'p57-blr-vmr',
        allowedLocationIds: [locationId],
        exclusiveAudience: p.audienceRestriction && p.audienceRestriction !== 'general_public' ? p.audienceRestriction : null,
      };
      const durationDays = durationToDays(p.duration, p.durationUnit);
      (catStmt as any).run({
        id, source_id: p.sourceId, source_file: p.sourceFile, source_index: p.sourceIndex,
        raw_block: p.rawBlock, raw_block_hash: p.rawBlockHash, name: p.name, product_class: p.productClass,
        exclusion_reason: p.exclusionReason ?? null, status, status_basis: basis, location_id: locationId,
        price: p.price, price_type: p.priceType, duration: p.duration, duration_unit: p.durationUnit,
        duration_days: durationDays, credits: p.credits, complimentary_credits: p.complimentaryCredits ?? null,
        credit_source: p.creditSource ?? null, unlimited_access: p.unlimitedAccess ? 1 : 0,
        private_session_count: p.privateSessionCount ?? null, is_intro_offer: p.isIntroOffer ? 1 : 0,
        audience_restriction: p.audienceRestriction ?? 'general_public', description: p.description ?? '',
        benefits_json: JSON.stringify(benefits), policies_json: JSON.stringify(p.policy ?? {}),
        eligibility_json: JSON.stringify(eligibility), observed_json: observed ? JSON.stringify(observed) : null,
        tags_json: JSON.stringify([
          p.unlimitedAccess ? 'unlimited' : p.credits ? 'credits' : 'access',
          p.productClass, p.isIntroOffer ? 'intro' : '', p.privateSessionCount ? 'private' : '',
        ].filter(Boolean)),
        parse_confidence: p.parseConfidence, warnings_json: JSON.stringify(p.warnings ?? []),
        manual_review_note: p.manualReviewNote ?? null, soft_deleted: p.softDeletedInSource ? 1 : 0,
        created_at: p.createdAt ?? null, modified_at: p.modifiedAt ?? null, updated_at: new Date().toISOString(),
      });

      catalogue.push({
        id, sourceId: p.sourceId, sourceIdTail: p.sourceIdTail, sourceFile: p.sourceFile, sourceIndex: p.sourceIndex,
        rawBlockHash: p.rawBlockHash, name: p.name, productClass: p.productClass as ProductClass,
        exclusionReason: p.exclusionReason, status: status as any, statusBasis: basis, locationId,
        locationName: LOCATIONS.find(l => l.id === locationId)!.name,
        price: p.price, priceType: p.priceType, duration: p.duration, durationUnit: p.durationUnit,
        credits: p.credits, complimentaryCredits: p.complimentaryCredits, creditSource: p.creditSource,
        unlimitedAccess: Boolean(p.unlimitedAccess), privateSessionCount: p.privateSessionCount,
        isIntroOffer: Boolean(p.isIntroOffer), audienceRestriction: p.audienceRestriction ?? 'general_public',
        description: p.description ?? '', benefits, policies: p.policy ?? {}, eligibility,
        createdAt: p.createdAt, modifiedAt: p.modifiedAt, softDeletedInSource: Boolean(p.softDeletedInSource),
        parseConfidence: p.parseConfidence, warnings: p.warnings ?? [], manualReviewNote: p.manualReviewNote ?? null,
        tags: [], observed: observed ? {
          product: observed.product, units: observed.units, revenue: observed.revenue,
          avgRealisedPrice: observed.avgRealisedPrice, discountGiven: observed.discountGiven,
          unitsLast90d: observed.unitsLast90d, revenueLast90d: observed.revenueLast90d,
          firstSale: observed.firstSale, lastSale: observed.lastSale,
        } : null,
      });
    }

    // ---------------------------------------------------------------- collections
    const colStmt = db.prepare(`INSERT INTO collections (id,name,slug,description,accent,kind) VALUES (?,?,?,?,?,?)`);
    COLLECTIONS.forEach(c => colStmt.run(c.id, c.name, c.slug, c.description, c.accent, c.kind));

    // ---------------------------------------------------------------- settings
    const settings = {
      guardrails: { ...DEFAULT_GUARDRAILS, updatedAt: new Date().toISOString(), updatedBy: 'usr_jimmeey' } as GuardrailConfig,
      costs: DEFAULT_COSTS,
      // Unlimited memberships cannot be valued without an attendance basis. Rather than leaving the
      // field empty (which would block every unlimited concept), the workspace starts from what the
      // supplied member-base export actually shows — median sessions per month — and states that
      // provenance wherever the figure is used. It is an editable assumption, not a rule.
      attendance: {
        ...DEFAULT_ATTENDANCE,
        visitsPerMonthDefault: customerBase?.behaviour?.avgSessionsPerMonth?.median ?? null,
        observedMedianVisitsPerMonth: customerBase?.behaviour?.avgSessionsPerMonth?.median ?? null,
        source: 'observed_export' as const,
        sourceNote: customerBase?.behaviour?.avgSessionsPerMonth?.median != null
          ? `Median of ${customerBase.behaviour.avgSessionsPerMonth.median} sessions per month across ${customerBase.behaviour.avgSessionsPerMonth.n} observed member-months in the supplied customer-base export. A starting assumption for valuing unlimited memberships — editable in Settings.`
          : 'No attendance figure could be derived from the supplied export. Set one in Settings before valuing unlimited memberships.',
        updatedAt: new Date().toISOString(),
        updatedBy: 'usr_jimmeey',
      },
      simulation: DEFAULT_SIMULATION,
      // A key saved in Settings → AI survives re-seeding: it is restored from the local key store.
      ai: readStoredAiConfig() ?? {
        provider: 'local_strategist', model: 'rules-v1', keyConfigured: false, keyHint: null,
        updatedAt: new Date().toISOString(), updatedBy: 'usr_jimmeey',
      },
      integrations: [
        { key: 'momence', label: 'Momence (studio management)', status: 'demo', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'The 88-record catalogue in this workspace was parsed from a supplied Momence membership export and is stored locally.',
          needs: 'Momence API credentials and written access to the export endpoint. Until then, catalogue updates are file imports only.' },
        { key: 'crm', label: 'CRM (leads & pipeline)', status: 'demo', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'Lead-funnel figures (9,892 leads → 3,058 trials → 1,145 sales, Bengaluru) come from a supplied CRM lead export.',
          needs: 'CRM API access or a scheduled report drop. No live pipeline sync is configured.' },
        { key: 'sales_db', label: 'Sales / transaction database', status: 'demo', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'Revenue analytics come from a supplied payments export: 6,274 lines, ₹26,404,316, 2023-11 to 2026-10.',
          needs: 'Read-only database credentials or a nightly extract. Direct query access is not configured.' },
        { key: 'sheets', label: 'Google Sheets', status: 'not_connected', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'No sheet is linked. Exports from this workspace are downloaded as files and shared by hand.',
          needs: 'Google Workspace authorisation for the studio account, plus the spreadsheet IDs to write to.' },
        { key: 'marketing_automation', label: 'Marketing automation', status: 'not_connected', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'Campaign copy is generated and copied out manually from the campaign workspace.',
          needs: 'Marketing platform credentials and approval of which audience lists may be mailed.' },
        { key: 'n8n', label: 'n8n workflows', status: 'not_connected', endpoint: null, verifiedAt: null, verifiedBy: null,
          detail: 'No workflow is triggered by this workspace. Nothing is sent anywhere automatically.',
          needs: 'An n8n instance URL and a webhook path, then a human verification recorded against this row.' },
      ],
    };
    const setStmt = db.prepare(`INSERT INTO settings (key,value_json,updated_at,updated_by) VALUES (?,?,?,?)`);
    const ts = new Date().toISOString();
    Object.entries(settings).forEach(([k, v]) => setStmt.run(k, JSON.stringify(v), ts, 'usr_jimmeey'));

    // ---------------------------------------------------------------- offers
    const guardrails = settings.guardrails as GuardrailConfig;
    const inserts = seedOffers({ db, catalogue, guardrails, evidence });

    // ---------------------------------------------------------------- campaigns
    seedCampaigns(db, inserts, catalogue);

    // ---------------------------------------------------------------- supporting activity
    seedCollaboration(db, inserts);

    db.prepare(`INSERT OR REPLACE INTO meta (key,value) VALUES ('seed_version',?)`).run(SEED_VERSION);
    db.prepare(`INSERT OR REPLACE INTO meta (key,value) VALUES ('seed_source','data/derived/catalogue.parsed.json + sales_performance.json + lead_funnel.json + customer_base.json + capacity_utilisation.json')`).run();
    db.prepare(`INSERT OR REPLACE INTO meta (key,value) VALUES ('engine_version',?)`).run(ENGINE_VERSION);
    db.prepare(`INSERT OR REPLACE INTO meta (key,value) VALUES ('seeded_at',?)`).run(new Date().toISOString());
  });

  tx();
  return { catalogue: parsed.length, offers: (db.prepare(`SELECT COUNT(*) c FROM offers`).get() as any).c };
}

function readDerivedJson<T>(file: string): T | null {
  const p = path.join(DATA_DIR, 'derived', file);
  if (!fs.existsSync(p)) return null;
  try { return JSON.parse(fs.readFileSync(p, 'utf8')) as T; } catch { return null; }
}

