function seedOffers(args: { db: Database.Database; catalogue: CatalogueProduct[]; guardrails: GuardrailConfig; evidence: EvidenceContext }) {
  const { db, catalogue, guardrails, evidence } = args;
  const insert = db.prepare(`INSERT INTO offers (
    id, code, name, internal_title, description, promo_copy, status, origin, base_product_id, base_product_name,
    location_ids, components, audience_segments, objectives, eligibility, terms, tags, collection_ids, campaign_id,
    owner_id, collaborator_ids, internal_notes, created_at, updated_at, published_at, expires_on, version,
    approved_version, requires_reapproval, favourite, pinned, archived_at, metrics_json, generation_json, concept_only)
    VALUES (@id,@code,@name,@internal_title,@description,@promo_copy,@status,@origin,@base_product_id,@base_product_name,
    @location_ids,@components,@audience_segments,@objectives,@eligibility,@terms,@tags,@collection_ids,@campaign_id,
    @owner_id,@collaborator_ids,@internal_notes,@created_at,@updated_at,@published_at,@expires_on,@version,
    @approved_version,@requires_reapproval,@favourite,@pinned,@archived_at,@metrics_json,@generation_json,@concept_only)`);

  const ctx = { catalogue, guardrails, costs: DEFAULT_COSTS, attendance: DEFAULT_ATTENDANCE };
  const created: { id: string; name: string; status: string; code: string; ownerId: string; proposal?: OfferProposal; baseProductId: string | null }[] = [];
  let counter = 100;

  const makeOffer = (input: {
    name: string; internalTitle: string; description: string; promoCopy: string; status: string; origin: string;
    baseProductId: string | null; components: any[]; audience: AudienceSegment[]; objectives: CommercialObjective[];
    eligibility: any; terms: OfferTerms; tags: string[]; collectionIds: string[]; ownerId: string;
    conceptOnly: boolean; generation: any; createdAt: string; updatedAt: string; approvedVersion?: number | null;
    collaboratorIds?: string[]; campaignId?: string | null; favourite?: boolean; pinned?: boolean; publishedAt?: string | null; expiresOn?: string | null;
    internalNotes?: string;
  }) => {
    // Deterministic ids: a seeded offer keeps the same address across reseeds, so a link, a note or
    // a conversation about "P57-BLR-104" still points at the same record tomorrow.
    const code = `P57-BLR-${++counter}`;
    const id = `off_seed_${code.split('-')[2]}`;
    const base = input.baseProductId ? catalogue.find(p => p.id === input.baseProductId) ?? null : null;
    // Resolve location scope defensively: an offer is never assumed to be redeemable
    // at a location it was not scoped to.
    const scopedLocations: LocationId[] = (input.eligibility?.locationIds?.length
      ? input.eligibility.locationIds
      : input.eligibility?.allowedLocationIds?.length
        ? input.eligibility.allowedLocationIds
        : base ? [base.locationId] : ['p57-blr-vmr']);
    const eligibility: OfferEligibility = {
      audienceSegments: input.audience,
      customAudience: input.eligibility?.customAudience,
      newClientsOnly: Boolean(input.eligibility?.newClientsOnly),
      existingMembersOnly: Boolean(input.eligibility?.existingMembersOnly),
      lapsedOnly: Boolean(input.eligibility?.lapsedOnly),
      minLapsedDays: input.eligibility?.minLapsedDays ?? null,
      locationIds: scopedLocations,
      purchaseLimitPerMember: input.eligibility?.purchaseLimitPerMember ?? null,
      requiresCode: Boolean(input.eligibility?.requiresCode),
      code: input.eligibility?.code ?? null,
      stackableWithOtherOffers: input.eligibility?.stackableWithOtherOffers ?? false,
      exclusions: input.eligibility?.exclusions ?? [],
    };
    const offer: Offer = {
      id, code, name: input.name, internalTitle: input.internalTitle, description: input.description,
      promoCopy: input.promoCopy, status: input.status as any, origin: input.origin as any,
      baseProductId: input.baseProductId, baseProductName: base?.name ?? null,
      locationIds: scopedLocations, components: input.components,
      audienceSegments: input.audience, objectives: input.objectives, eligibility,
      terms: input.terms, tags: input.tags, collectionIds: input.collectionIds, campaignId: input.campaignId ?? null,
      ownerId: input.ownerId, collaboratorIds: input.collaboratorIds ?? [], internalNotes: input.internalNotes ?? '',
      createdAt: input.createdAt, updatedAt: input.updatedAt, publishedAt: input.publishedAt ?? null,
      expiresOn: input.expiresOn ?? null, version: 1, approvedVersion: input.approvedVersion ?? null,
      requiresReapproval: false, favourite: input.favourite ?? false, pinned: input.pinned ?? false, archivedAt: null,
      metricsSnapshot: null, generationContext: input.generation, conceptOnly: input.conceptOnly,
    };
    const { metrics } = computeOfferMetrics(offer, { ...ctx, allOffers: [] });
    offer.metricsSnapshot = metrics;
    (insert as any).run({
      id, code, name: offer.name, internal_title: offer.internalTitle, description: offer.description,
      promo_copy: offer.promoCopy, status: offer.status, origin: offer.origin,
      base_product_id: offer.baseProductId, base_product_name: offer.baseProductName,
      location_ids: JSON.stringify(offer.locationIds), components: JSON.stringify(offer.components),
      audience_segments: JSON.stringify(offer.audienceSegments), objectives: JSON.stringify(offer.objectives),
      eligibility: JSON.stringify(offer.eligibility), terms: JSON.stringify(offer.terms),
      tags: JSON.stringify(offer.tags), collection_ids: JSON.stringify(offer.collectionIds),
      campaign_id: offer.campaignId, owner_id: offer.ownerId, collaborator_ids: JSON.stringify(offer.collaboratorIds),
      internal_notes: offer.internalNotes, created_at: offer.createdAt, updated_at: offer.updatedAt,
      published_at: offer.publishedAt, expires_on: offer.expiresOn, version: 1,
      approved_version: offer.approvedVersion, requires_reapproval: 0, favourite: offer.favourite ? 1 : 0,
      pinned: offer.pinned ? 1 : 0, archived_at: null, metrics_json: JSON.stringify(metrics),
      generation_json: JSON.stringify(input.generation), concept_only: input.conceptOnly ? 1 : 0,
    });
    db.prepare(`INSERT INTO offer_versions (id,offer_id,version,snapshot_json,change_summary,changed_fields,author_id,approval_state,created_at)
      VALUES (?,?,?,?,?,?,?,?,?)`).run(`ver_${crypto.randomBytes(6).toString('hex')}`, id, 1, JSON.stringify(offer),
      'Initial version created in the offer workspace.', '[]', input.ownerId, offer.status, input.createdAt);
    created.push({ id, name: offer.name, status: offer.status, code, ownerId: input.ownerId, baseProductId: offer.baseProductId });
    return id;
  };

  // ---- generated concepts from curated briefs --------------------------------
  const daysAgo = (n: number) => new Date(Date.parse('2026-10-16T06:30:00.000Z') - n * 86400000).toISOString();
  let i = 0;
  for (const brief of BRIEFS) {
    const proposals = generateProposals({
      catalogue, guardrails, costs: DEFAULT_COSTS, attendance: DEFAULT_ATTENDANCE,
      audience: brief.audience, objectives: brief.objectives, locationIds: brief.locationIds,
      controls: brief.controls, constraints: brief.constraints, count: brief.count,
      presetId: brief.presetId, seed: 1000 + i * 37, prompt: brief.prompt, mode: 'guided', evidence,
    });
    for (const prop of proposals) {
      const base = catalogue.find(p => p.id === prop.baseProductId)!;
      const messages = generateMessages({
        name: prop.name, description: prop.strategy.concept, locationLabel: base.locationName,
        economics: prop.economics, audienceSegments: brief.audience, objectives: brief.objectives,
        deadlines: { purchaseDeadline: prop.terms.purchaseDeadline ?? null },
        baseProductName: base.name,
      });
      makeOffer({
        name: prop.name,
        internalTitle: `${prop.angleLabel} · ${base.name}`,
        description: prop.strategy.concept,
        promoCopy: messages.whatsappShort,
        status: brief.targetStatus,
        origin: 'guided',
        baseProductId: prop.baseProductId,
        components: prop.components,
        audience: prop.audienceSegments,
        objectives: prop.objectives,
        eligibility: prop.eligibility,
        terms: prop.terms,
        tags: prop.tags,
        collectionIds: brief.collectionIds,
        ownerId: brief.ownerId,
        conceptOnly: true,
        generation: {
          engine: 'local_strategist', engineVersion: ENGINE_VERSION, mode: 'guided',
          provider: 'local_strategist',
          providerLabel: 'Local strategist engine (deterministic, catalogue-driven — no external model connected)',
          prompt: brief.prompt, preset: brief.presetId, controls: brief.controls,
          catalogueSnapshot: `catalogue@${new Date().toISOString().slice(0, 10)}`,
          evidenceUsed: ['Observed Bengaluru sales export', 'CRM lead funnel export', 'Member lifecycle export'],
          notes: [prop.strategy.facts[0] ?? ''],
          generatedAt: daysAgo(14 - (i % 12)),
        },
        createdAt: daysAgo(30 - (i % 25)),
        updatedAt: daysAgo(14 - (i % 12)),
        approvedVersion: brief.targetStatus === 'approved' || brief.targetStatus === 'published' ? 1 : null,
        publishedAt: brief.targetStatus === 'published' ? daysAgo(12) : null,
        // Published offers intentionally land inside the decision window so the
        // command centre has real expiry work to surface.
        expiresOn: brief.targetStatus === 'published' ? EXPIRY_WINDOW[i % EXPIRY_WINDOW.length] : null,
        collaboratorIds: brief.ownerId === 'usr_prathap' ? ['usr_api'] : ['usr_prathap'],
        favourite: i % 7 === 0,
        pinned: i % 9 === 0,
      });
      i++;
    }
  }

  // ---- historical, previously executed promotions (from the source export) ----
  const historicals: { productName: string; collection: string[]; status: 'published' | 'expired'; note: string }[] = [
    { productName: 'New Client Intro Pack', collection: ['col-new-client', 'col-historical'], status: 'published', note: 'Standing new-client entry product, sold continuously in the observed sales export.' },
    { productName: 'Studio Newcomer 2 for 1', collection: ['col-new-client', 'col-historical'], status: 'published', note: 'Two classes for the price of one for new clients.' },
    { productName: 'Anniversary Starter Pack', collection: ['col-festive', 'col-historical'], status: 'expired', note: 'Anniversary campaign pack: 12 classes with 2 complimentary classes.' },
    { productName: 'Festive 5 Package', collection: ['col-festive', 'col-historical'], status: 'expired', note: 'Festive season 5-class pack.' },
    { productName: 'Summer Bootcamp - Studio 6 Week Unlimited', collection: ['col-limited', 'col-historical'], status: 'expired', note: 'Six-week summer programme with nutrition and check-in support.' },
    { productName: 'The Big 85 Flex: Anniversary Edition', collection: ['col-premium', 'col-historical'], status: 'expired', note: '91 classes over 360 days — anniversary long-commitment product.' },
    { productName: 'Physique 57 x Mama Heals - Studio Intro Pack', collection: ['col-corporate', 'col-historical'], status: 'published', note: 'Partner collaboration for Mama Heals members: 4 credits for the price of 3.' },
    { productName: 'Kickstarter Pack - 5 classes in 10 days', collection: ['col-new-client', 'col-historical'], status: 'published', note: 'Newcomer pack: five credits to complete in ten days.' },
    { productName: 'Studio Hybrid 1 Month unlimited', collection: ['col-premium', 'col-historical'], status: 'published', note: 'Hybrid one-month unlimited proposition at ₹17,750.' },
  ];
  for (const h of historicals) {
    const base = catalogue.find(p => p.name === h.productName);
    if (!base || !base.price) continue;
    const terms: OfferTerms = {
      pricingMode: 'value_add', discountPct: null, discountAmount: null, sellingPrice: base.price,
      validityDays: durationToDays(base.duration, base.durationUnit), creditsIncluded: base.unlimitedAccess ? null : base.credits,
      bonusCredits: 0, complimentaryClasses: base.complimentaryCredits ?? 0,
      privateSessions: base.privateSessionCount ?? 0, guestPasses: base.policies.guestPasses ?? 0,
      validityExtensionDays: 0, purchaseDeadline: null, redeemableFrom: null, redeemableTo: null,
    };
    const id = makeOffer({
      name: base.name, internalTitle: `Executed product · ${base.name}`,
      description: h.note, promoCopy: '', status: h.status, origin: 'manual',
      baseProductId: base.id, components: [], audience: [], objectives: [],
      eligibility: base.eligibility, terms, tags: ['historical-reference'], collectionIds: h.collection,
      ownerId: 'usr_shifa', conceptOnly: false,
      generation: {
        engine: 'import', engineVersion: ENGINE_VERSION, mode: 'seed', provider: 'local_strategist',
        providerLabel: 'Imported from the membership export', notes: [h.note],
        evidenceUsed: ['Membership export', 'Bengaluru sales export'], generatedAt: base.createdAt ?? daysAgo(300),
      },
      createdAt: base.createdAt ?? daysAgo(300), updatedAt: base.modifiedAt ?? daysAgo(120),
      approvedVersion: 1, publishedAt: base.createdAt ?? daysAgo(300), collaboratorIds: ['usr_prathap'],
    });
    const observed = base.observed;
    if (observed) {
      db.prepare(`INSERT INTO performance_records (id,offer_id,metric,label,expected,actual,unit,basis,source,period,created_at,created_by)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(
        `prf_${crypto.randomBytes(6).toString('hex')}`, id, 'units_sold', 'Units sold (observed)', null, observed.units, 'units',
        'Observed in the Bengaluru payments export, not an estimate.', 'Sales - Raw - Sales (23).csv', `${observed.firstSale} → ${observed.lastSale}`,
        new Date().toISOString(), 'usr_jimmeey');
      db.prepare(`INSERT INTO performance_records (id,offer_id,metric,label,expected,actual,unit,basis,source,period,created_at,created_by)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(
        `prf_${crypto.randomBytes(6).toString('hex')}`, id, 'revenue', 'Revenue (observed)', null, observed.revenue, 'INR',
        'Observed in the Bengaluru payments export, not an estimate.', 'Sales - Raw - Sales (23).csv', `${observed.firstSale} → ${observed.lastSale}`,
        new Date().toISOString(), 'usr_jimmeey');
    }
  }

  return created;
}

